-- Local copy of the live wealth_os tables the contribution engine touches (read 18 Nov 2026).
create extension if not exists pgcrypto;
create schema if not exists wealth_os;
create schema if not exists auth;
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid', true), '')::uuid $$;
create table wealth_os.account_deposits (id uuid default gen_random_uuid() not null, account_id uuid not null, month_key text not null, amount numeric not null, last_edited_by text, last_edited_at timestamp with time zone, sacrifice_amount numeric, relief_amount numeric);
create table wealth_os.account_months (id uuid default gen_random_uuid() not null, account_id uuid not null, month_key text not null, value numeric not null, last_edited_by text, last_edited_at timestamp with time zone, carried_forward boolean default false not null);
create table wealth_os.clients (id uuid default gen_random_uuid() not null, user_id uuid, first_name text default '', last_name text default '', created_at timestamptz default now() not null, onboarding_complete boolean default false not null);
create table wealth_os.accounts (id uuid default gen_random_uuid() not null, client_id uuid not null, provider text default '', type text not null, value numeric default 0 not null, created_at timestamp with time zone default now() not null, return_pct numeric, contribution numeric, contribution_personal numeric, contribution_sacrifice numeric, last_updated date, last_edited_by text, last_edited_at timestamp with time zone, opening_contributions numeric, cash_balance numeric, is_manual_priced boolean default false not null, has_contribution_rule boolean default false not null);
create table wealth_os.contribution_flags (id uuid default gen_random_uuid() not null, account_id uuid not null, rule_id uuid not null, income_id uuid, old_amount numeric, old_frequency text, new_amount numeric, new_frequency text, suggested jsonb, status text default 'pending' not null, created_at timestamp with time zone default now() not null, resolved_at timestamp with time zone, resolved_by text);
create table wealth_os.contribution_rule_allocations (id uuid default gen_random_uuid() not null, rule_id uuid not null, holding_id uuid not null, weight_pct numeric(6,3), amount numeric(12,2), sort_order smallint default 0 not null);
create table wealth_os.contribution_rule_state (account_id uuid not null, start_date date not null, next_uplift_date date, last_reviewed_at date, last_review_source text);
create table wealth_os.contribution_rules (id uuid default gen_random_uuid() not null, account_id uuid not null, version integer not null, effective_from date not null, effective_to date, basis text not null, allocation_method text not null, total_amount numeric(12,2), day_of_month smallint not null, annual_uplift_pct numeric(5,2) default 0 not null, linked_income_id uuid, gross_annual_salary numeric(12,2), pensionable_basis text, employee_pct numeric(5,2), employer_pct numeric(5,2), employer_match_cap_pct numeric(5,2), contribution_method text, change_reason text, created_at timestamp with time zone default now() not null, created_by text, employer_ni_passon_pct numeric(5,2) default 0 not null);
create table wealth_os.contribution_runs (id uuid default gen_random_uuid() not null, account_id uuid not null, rule_id uuid not null, run_date date not null, month_key text not null, total_amount numeric(12,2) not null, employee_amount numeric(12,2), employer_amount numeric(12,2), sacrifice_amount numeric(12,2), relief_amount numeric(12,2), allocations jsonb not null, status text default 'applied' not null, correction_note text, corrected_by text, corrected_at timestamp with time zone, applied_at timestamp with time zone default now() not null);
create table wealth_os.holding_months (id uuid default gen_random_uuid() not null, holding_id uuid not null, month_key text not null, value numeric not null, last_edited_by text, last_edited_at timestamp with time zone, carried_forward boolean default false not null);
create table wealth_os.holdings (id uuid default gen_random_uuid() not null, account_id uuid not null, name text default '' not null, ticker text, units numeric, avg_open numeric, cost_basis numeric, value numeric default 0 not null, last_price numeric, created_at timestamp with time zone default now() not null, last_edited_by text, last_edited_at timestamp with time zone, price_source text default 'manual' not null, value_checked_at date);
create table wealth_os.income (id uuid default gen_random_uuid() not null, client_id uuid not null, owner text default 'client' not null, type text default '', amount numeric default 0 not null, frequency text default '', last_edited_by text, last_edited_at timestamp with time zone);
create table wealth_os.pension_config (key text not null, value numeric not null, note text);
create table wealth_os.profiles (user_id uuid not null, role text not null, created_at timestamp with time zone default now() not null, first_name text);
alter table wealth_os.account_deposits add constraint account_deposits_account_id_month_key_key UNIQUE (account_id, month_key);
alter table wealth_os.account_deposits add constraint account_deposits_pkey PRIMARY KEY (id);
alter table wealth_os.account_months add constraint account_months_account_id_month_key_key UNIQUE (account_id, month_key);
alter table wealth_os.account_months add constraint account_months_pkey PRIMARY KEY (id);
alter table wealth_os.accounts add constraint accounts_pkey PRIMARY KEY (id);
alter table wealth_os.clients add constraint clients_pkey PRIMARY KEY (id);
alter table wealth_os.accounts add constraint accounts_client_id_fkey FOREIGN KEY (client_id) REFERENCES wealth_os.clients(id) ON DELETE CASCADE;
alter table wealth_os.account_deposits add constraint account_deposits_account_id_fkey FOREIGN KEY (account_id) REFERENCES wealth_os.accounts(id) ON DELETE CASCADE;
alter table wealth_os.account_months add constraint account_months_account_id_fkey FOREIGN KEY (account_id) REFERENCES wealth_os.accounts(id) ON DELETE CASCADE;
alter table wealth_os.income add constraint income_pkey PRIMARY KEY (id);
alter table wealth_os.contribution_rules add constraint contribution_rules_pkey PRIMARY KEY (id);
alter table wealth_os.contribution_rules add constraint contribution_rules_account_id_fkey FOREIGN KEY (account_id) REFERENCES wealth_os.accounts(id) ON DELETE CASCADE;
alter table wealth_os.contribution_rules add constraint contribution_rules_allocation_method_check CHECK ((allocation_method = ANY (ARRAY['percentage'::text, 'manual'::text])));
alter table wealth_os.contribution_rules add constraint contribution_rules_basis_check CHECK ((basis = ANY (ARRAY['fixed'::text, 'salary_derived'::text])));
alter table wealth_os.contribution_rules add constraint contribution_rules_check CHECK (((basis <> 'salary_derived'::text) OR (allocation_method = 'percentage'::text)));
alter table wealth_os.contribution_rules add constraint contribution_rules_check1 CHECK (((basis <> 'fixed'::text) OR (allocation_method <> 'percentage'::text) OR (total_amount IS NOT NULL)));
alter table wealth_os.contribution_rules add constraint contribution_rules_contribution_method_check CHECK ((contribution_method = ANY (ARRAY['salary_sacrifice'::text, 'relief_at_source'::text])));
alter table wealth_os.contribution_rules add constraint contribution_rules_day_of_month_check CHECK (((day_of_month >= 1) AND (day_of_month <= 28)));
alter table wealth_os.holdings add constraint holdings_pkey PRIMARY KEY (id);
alter table wealth_os.holdings add constraint holdings_account_id_fkey FOREIGN KEY (account_id) REFERENCES wealth_os.accounts(id) ON DELETE CASCADE;
alter table wealth_os.holdings add constraint holdings_price_source_check CHECK ((price_source = ANY (ARRAY['auto_us'::text, 'manual'::text])));
alter table wealth_os.contribution_rule_allocations add constraint contribution_rule_allocations_rule_id_holding_id_key UNIQUE (rule_id, holding_id);
alter table wealth_os.contribution_rule_allocations add constraint contribution_rule_allocations_holding_id_fkey FOREIGN KEY (holding_id) REFERENCES wealth_os.holdings(id);
alter table wealth_os.contribution_rule_allocations add constraint contribution_rule_allocations_rule_id_fkey FOREIGN KEY (rule_id) REFERENCES wealth_os.contribution_rules(id) ON DELETE CASCADE;
alter table wealth_os.contribution_rule_state add constraint contribution_rule_state_pkey PRIMARY KEY (account_id);
alter table wealth_os.contribution_rule_state add constraint contribution_rule_state_last_review_source_check CHECK ((last_review_source = ANY (ARRAY['created'::text, 'manual_edit'::text, 'income_change'::text, 'annual_uplift'::text])));
alter table wealth_os.contribution_runs add constraint contribution_runs_account_id_run_date_key UNIQUE (account_id, run_date);
alter table wealth_os.contribution_runs add constraint contribution_runs_pkey PRIMARY KEY (id);
alter table wealth_os.contribution_runs add constraint contribution_runs_status_check CHECK ((status = ANY (ARRAY['applied'::text, 'reversed'::text, 'adjusted'::text])));
alter table wealth_os.holding_months add constraint holding_months_holding_id_month_key_key UNIQUE (holding_id, month_key);
alter table wealth_os.pension_config add constraint pension_config_pkey PRIMARY KEY (key);
alter table wealth_os.profiles add constraint profiles_pkey PRIMARY KEY (user_id);
insert into wealth_os.pension_config values ('qe_lower', 6240, null), ('qe_upper', 50270, null), ('ras_relief_gross_up', 0.25, null), ('ni_primary_threshold', 12570, null), ('ni_upper_earnings_limit', 50270, null), ('ni_employee_main_rate', 0.08, null), ('ni_employee_upper_rate', 0.02, null), ('ni_secondary_threshold', 5000, null), ('ni_employer_rate', 0.15, null);
